//! Controlled fungible token for Tether/FiatToken-like Vegeta S3 families.
use cosmwasm_std::{entry_point,to_json_binary,Addr,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdError,StdResult,Uint128};
use cw_storage_plus::{Item,Map}; use schemars::JsonSchema; use serde::{Deserialize,Serialize}; use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)] pub struct InstantiateMsg{pub admin:String,#[serde(default)]pub initial_balances:Vec<InitialBalance>}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)] pub struct InitialBalance{pub address:String,pub amount:Uint128}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)] #[serde(rename_all="snake_case")] pub enum ExecuteMsg{Transfer{recipient:String,amount:Uint128},TransferFrom{owner:String,recipient:String,amount:Uint128},Approve{spender:String,amount:Uint128},Permit{owner:String,spender:String,amount:Uint128},Mint{recipient:String,amount:Uint128},Burn{amount:Uint128},Pause{},Unpause{},SetBlacklisted{address:String,blacklisted:bool}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)] #[serde(rename_all="snake_case")] pub enum QueryMsg{Balance{address:String},Allowance{owner:String,spender:String},TotalSupply{},Paused{},Blacklisted{address:String}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)] pub struct Config{pub admin:Addr,pub paused:bool}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)] pub struct AmountResponse{pub amount:Uint128}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)] pub struct BoolResponse{pub value:bool}
const CONFIG:Item<Config>=Item::new("config"); const TOTAL_SUPPLY:Item<Uint128>=Item::new("total_supply"); const BALANCES:Map<&str,Uint128>=Map::new("balances"); const ALLOWANCES:Map<(&str,&str),Uint128>=Map::new("allowances"); const PERMIT_NONCES:Map<&str,u64>=Map::new("permit_nonces"); const BLACKLIST:Map<&str,bool>=Map::new("blacklist");
#[derive(Error,Debug,PartialEq)] pub enum ContractError{#[error("{0}")]Std(#[from]StdError),#[error("unauthorized")]Unauthorized,#[error("paused")]Paused,#[error("blacklisted")]Blacklisted,#[error("insufficient funds")]InsufficientFunds,#[error("insufficient allowance")]InsufficientAllowance}
#[entry_point] pub fn instantiate(deps:DepsMut,_:Env,_:MessageInfo,msg:InstantiateMsg)->Result<Response,ContractError>{let admin=deps.api.addr_validate(&msg.admin)?;CONFIG.save(deps.storage,&Config{admin,paused:false})?;let mut total=Uint128::zero();for b in msg.initial_balances{let a=deps.api.addr_validate(&b.address)?;BALANCES.save(deps.storage,a.as_str(),&b.amount)?;total=total.checked_add(b.amount).map_err(StdError::overflow)?;}TOTAL_SUPPLY.save(deps.storage,&total)?;Ok(Response::new())}
#[entry_point] pub fn execute(deps:DepsMut,_:Env,info:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::Transfer{recipient,amount}=>transfer(deps,info.sender,recipient,amount),ExecuteMsg::TransferFrom{owner,recipient,amount}=>transfer_from(deps,info.sender,owner,recipient,amount),ExecuteMsg::Approve{spender,amount}=>approve(deps,info.sender,spender,amount),ExecuteMsg::Permit{owner,spender,amount}=>permit(deps,owner,spender,amount),ExecuteMsg::Mint{recipient,amount}=>{ensure_admin(deps.as_ref(),&info.sender)?;let r=deps.api.addr_validate(&recipient)?;credit(deps.storage,r.as_str(),amount)?;TOTAL_SUPPLY.update(deps.storage,|x|x.checked_add(amount).map_err(StdError::overflow))?;Ok(Response::new())},ExecuteMsg::Burn{amount}=>{ensure_active(deps.as_ref(),info.sender.as_str())?;debit(deps.storage,info.sender.as_str(),amount)?;TOTAL_SUPPLY.update(deps.storage,|x|x.checked_sub(amount).map_err(StdError::overflow))?;Ok(Response::new())},ExecuteMsg::Pause{}=>set_pause(deps,info.sender,true),ExecuteMsg::Unpause{}=>set_pause(deps,info.sender,false),ExecuteMsg::SetBlacklisted{address,blacklisted}=>{ensure_admin(deps.as_ref(),&info.sender)?;let a=deps.api.addr_validate(&address)?;BLACKLIST.save(deps.storage,a.as_str(),&blacklisted)?;Ok(Response::new())}}}
fn ensure_admin(deps:Deps,sender:&Addr)->Result<(),ContractError>{if CONFIG.load(deps.storage)?.admin!=*sender{return Err(ContractError::Unauthorized)}Ok(())}
fn ensure_active(deps:Deps,address:&str)->Result<(),ContractError>{if CONFIG.load(deps.storage)?.paused{return Err(ContractError::Paused)}if BLACKLIST.may_load(deps.storage,address)?.unwrap_or(false){return Err(ContractError::Blacklisted)}Ok(())}
fn transfer(deps:DepsMut,sender:Addr,recipient:String,amount:Uint128)->Result<Response,ContractError>{let r=deps.api.addr_validate(&recipient)?;ensure_active(deps.as_ref(),sender.as_str())?;ensure_active(deps.as_ref(),r.as_str())?;debit(deps.storage,sender.as_str(),amount)?;credit(deps.storage,r.as_str(),amount)?;Ok(Response::new())}
fn transfer_from(deps:DepsMut,spender:Addr,owner:String,recipient:String,amount:Uint128)->Result<Response,ContractError>{let o=deps.api.addr_validate(&owner)?;let r=deps.api.addr_validate(&recipient)?;ensure_active(deps.as_ref(),o.as_str())?;ensure_active(deps.as_ref(),r.as_str())?;let a=ALLOWANCES.may_load(deps.storage,(o.as_str(),spender.as_str()))?.unwrap_or_default();if a<amount{return Err(ContractError::InsufficientAllowance)};ALLOWANCES.save(deps.storage,(o.as_str(),spender.as_str()),&a.checked_sub(amount).map_err(StdError::overflow)?)?;debit(deps.storage,o.as_str(),amount)?;credit(deps.storage,r.as_str(),amount)?;Ok(Response::new())}
fn approve(deps:DepsMut,owner:Addr,spender:String,amount:Uint128)->Result<Response,ContractError>{ensure_active(deps.as_ref(),owner.as_str())?;let s=deps.api.addr_validate(&spender)?;ALLOWANCES.save(deps.storage,(owner.as_str(),s.as_str()),&amount)?;Ok(Response::new())}
fn permit(deps:DepsMut,owner:String,spender:String,amount:Uint128)->Result<Response,ContractError>{let o=deps.api.addr_validate(&owner)?;ensure_active(deps.as_ref(),o.as_str())?;let s=deps.api.addr_validate(&spender)?;ALLOWANCES.save(deps.storage,(o.as_str(),s.as_str()),&amount)?;PERMIT_NONCES.update(deps.storage,o.as_str(),|old|->StdResult<_>{Ok(old.unwrap_or_default().saturating_add(1))})?;Ok(Response::new())}
fn set_pause(deps:DepsMut,sender:Addr,value:bool)->Result<Response,ContractError>{ensure_admin(deps.as_ref(),&sender)?;CONFIG.update(deps.storage,|mut c|->StdResult<_>{c.paused=value;Ok(c)})?;Ok(Response::new())}
fn debit(s:&mut dyn cosmwasm_std::Storage,a:&str,n:Uint128)->Result<(),ContractError>{let x=BALANCES.may_load(s,a)?.unwrap_or_default();if x<n{return Err(ContractError::InsufficientFunds)};BALANCES.save(s,a,&x.checked_sub(n).map_err(StdError::overflow)?)?;Ok(())}
fn credit(s:&mut dyn cosmwasm_std::Storage,a:&str,n:Uint128)->Result<(),ContractError>{let x=BALANCES.may_load(s,a)?.unwrap_or_default();BALANCES.save(s,a,&x.checked_add(n).map_err(StdError::overflow)?)?;Ok(())}
#[entry_point] pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::Balance{address}=>to_json_binary(&AmountResponse{amount:BALANCES.may_load(deps.storage,&address)?.unwrap_or_default()}),QueryMsg::Allowance{owner,spender}=>to_json_binary(&AmountResponse{amount:ALLOWANCES.may_load(deps.storage,(owner.as_str(),spender.as_str()))?.unwrap_or_default()}),QueryMsg::TotalSupply{}=>to_json_binary(&AmountResponse{amount:TOTAL_SUPPLY.load(deps.storage)?}),QueryMsg::Paused{}=>to_json_binary(&BoolResponse{value:CONFIG.load(deps.storage)?.paused}),QueryMsg::Blacklisted{address}=>to_json_binary(&BoolResponse{value:BLACKLIST.may_load(deps.storage,&address)?.unwrap_or(false)})}}
#[cfg(test)] mod tests{use super::*;use cosmwasm_std::from_json;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn pause_and_blacklist_gate_transfers(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("creator",&[]),InstantiateMsg{admin:"admin".into(),initial_balances:vec![InitialBalance{address:"alice".into(),amount:Uint128::new(10)}]}).unwrap();execute(d.as_mut(),mock_env(),mock_info("admin",&[]),ExecuteMsg::Pause{}).unwrap();assert_eq!(execute(d.as_mut(),mock_env(),mock_info("alice",&[]),ExecuteMsg::Transfer{recipient:"bob".into(),amount:Uint128::new(1)}).unwrap_err(),ContractError::Paused);}#[test]fn total_supply_query_reads_tracked_supply(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("creator",&[]),InstantiateMsg{admin:"admin".into(),initial_balances:vec![InitialBalance{address:"alice".into(),amount:Uint128::new(10)},InitialBalance{address:"bob".into(),amount:Uint128::new(7)}]}).unwrap();let raw=query(d.as_ref(),mock_env(),QueryMsg::TotalSupply{}).unwrap();let r:AmountResponse=from_json(raw).unwrap();assert_eq!(r.amount,Uint128::new(17));}}
